var COMMON=['password','123456','qwerty','admin','letmein','iloveyou','welcome','abc123','111111','sunshine','football','monkey'];
function hasSequence(p){
  var s=p.toLowerCase();
  for(var i=0;i+2<s.length;i++){
    var a=s.charCodeAt(i), b=s.charCodeAt(i+1), c=s.charCodeAt(i+2);
    if(b===a+1 && c===b+1) return true;
    if(b===a-1 && c===b-1) return true;
  }
  return false;
}
function checkPassword(pwd, policy){
  policy=policy||{};
  pwd=String(pwd||'');
  var minLen=policy.minLen!=null?policy.minLen:12;
  var maxLen=policy.maxLen!=null?policy.maxLen:64;
  var reqUpper=policy.upper, reqLower=policy.lower, reqDigit=policy.digit, reqSpecial=policy.special;
  var noRepeat=policy.noRepeat, noSeq=policy.noSeq, noCommon=policy.noCommon;
  var issues=[];
  if(pwd.length<minLen) issues.push('长度不足（至少 '+minLen+' 位）');
  if(pwd.length>maxLen) issues.push('超出最大长度（'+maxLen+' 位）');
  var hasUpper=/[A-Z]/.test(pwd), hasLower=/[a-z]/.test(pwd), hasDigit=/\d/.test(pwd), hasSpecial=/[^A-Za-z0-9]/.test(pwd);
  if(reqUpper && !hasUpper) issues.push('缺少大写字母');
  if(reqLower && !hasLower) issues.push('缺少小写字母');
  if(reqDigit && !hasDigit) issues.push('缺少数字');
  if(reqSpecial && !hasSpecial) issues.push('缺少特殊符号');
  if(noRepeat && /(.)\1\1/.test(pwd)) issues.push('含连续重复字符');
  if(noSeq && hasSequence(pwd)) issues.push('含连续序列（如 abc/123）');
  if(noCommon){ var low=pwd.toLowerCase(); for(var i=0;i<COMMON.length;i++){ if(low.indexOf(COMMON[i])>=0){ issues.push('命中常见弱口令'); break; } } }
  var classes=0; if(hasUpper)classes++; if(hasLower)classes++; if(hasDigit)classes++; if(hasSpecial)classes++;
  var score=Math.min(100, pwd.length*4 + classes*10 - issues.length*15);
  if(score<0)score=0;
  return {ok:issues.length===0, score:score, issues:issues, length:pwd.length, classes:classes};
}
function pick(s,rng){ return s.charAt(Math.floor(rng()*s.length)); }
function genPassword(policy, rng){
  policy=policy||{};
  var minLen=policy.minLen!=null?policy.minLen:12;
  var maxLen=policy.maxLen!=null?policy.maxLen:64;
  rng=rng||Math.random;
  var upper='ABCDEFGHJKLMNPQRSTUVWXYZ', lower='abcdefghijkmnopqrstuvwxyz', digit='23456789', special='!@#$%^&*';
  var full=upper+lower+digit+special;
  var need=[];
  if(policy.upper) need.push(pick(upper,rng));
  if(policy.lower) need.push(pick(lower,rng));
  if(policy.digit) need.push(pick(digit,rng));
  if(policy.special) need.push(pick(special,rng));
  var len=Math.max(minLen, need.length);
  for(var attempt=0; attempt<50; attempt++){
    var chars=need.slice();
    while(chars.length<len){ chars.push(full.charAt(Math.floor(rng()*full.length))); }
    for(var i=chars.length-1;i>0;i--){ var j=Math.floor(rng()*(i+1)); var t=chars[i]; chars[i]=chars[j]; chars[j]=t; }
    var cand=chars.join('');
    if(checkPassword(cand, policy).ok) return cand;
  }
  return chars.join('');
}
var EXPORTS={checkPassword:checkPassword, genPassword:genPassword, hasSequence:hasSequence, COMMON:COMMON};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.PasswordPolicyForgePure = EXPORTS; }
